INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63385676', 63385676, 'analyze_legacy', 'Provinsi DKI Jakarta', 'provinsi', 'UNIT PENGELOLA MUSEUM KESEJARAHAN JAKARTA', 'Penyediaan Jasa Pengolahan Air Limbah', 'Jasa Lainnya', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Barat (Kota)', 19475333, 'January 2026', 'APBD', 1, 1, '95 M3', 'Pekerjaan ini meliputi penyediaan jasa pengolahan air limbah melalui kegiatan penyedotan lumpur tinja pada Instalasi Pengolahan Air Limbah (IPAL), guna menjaga fungsi sistem sanitasi, mencegah pencemaran lingkungan, serta menjamin kesehatan dan kenyamanan lingkungan bangunan. Pelaksanaan pekerjaan mencakup penyedotan lumpur tinja secara berkala maupun sesuai kebutuhan, dengan memperhatikan standar keselamatan kerja, kebersihan, dan ketentuan lingkungan hidup yang berlaku.', 'Spesifikasi pekerjaan mencakup penyedotan lumpur tinja dari unit IPAL menggunakan armada dan peralatan khusus, pengangkutan lumpur tinja ke lokasi pengolahan yang berizin, serta pengolahan lumpur tinja sesuai standar teknis dan peraturan perundang-undangan di bidang pengelolaan air limbah. Seluruh rangkaian pekerjaan dilaksanakan oleh penyedia jasa yang memiliki izin resmi, tenaga teknis berkompeten, dan prosedur operasional yang aman, ramah lingkungan, serta terdokumentasi dengan baik sebagai bentuk pertanggungjawaban pelaksanaan kegiatan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 890458);
