INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63387679', 63387679, 'analyze_legacy', 'Provinsi DKI Jakarta', 'provinsi', 'UNIT PENGELOLA MUSEUM KESEJARAHAN JAKARTA', 'Belanja Iuran Jaminan Kesehatan, Kecelakaan, dan Kematian bagi Non ASN', 'Jasa Lainnya', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Barat (Kota)', 373402860, 'January 2026', 'APBD', 1, 1, '127 Orang 12 Bulan', 'Pekerjaan ini meliputi penyediaan dan pembayaran iuran jaminan sosial bagi pegawai Non ASN sebagai bentuk perlindungan terhadap risiko kesehatan, kecelakaan kerja, dan kematian, guna menjamin kesejahteraan serta keamanan sosial tenaga kerja dalam mendukung kelancaran pelaksanaan tugas dan fungsi organisasi. Pembayaran iuran dilaksanakan sesuai ketentuan peraturan perundang-undangan yang berlaku dan kebijakan pemerintah di bidang jaminan sosial tenaga kerja dan kesehatan.', 'Spesifikasi pekerjaan mencakup pembayaran iuran Jaminan Kesehatan, Jaminan Kecelakaan Kerja, dan Jaminan Kematian bagi pegawai Non ASN yang terdaftar sebagai peserta program jaminan sosial, sesuai besaran iuran dan mekanisme yang ditetapkan oleh instansi penyelenggara jaminan sosial. Pelaksanaan pembayaran dilakukan secara tepat waktu, tertib administrasi, dan dapat dipertanggungjawabkan, dengan dukungan dokumen kepesertaan dan bukti pembayaran yang sah sesuai ketentuan yang berlaku.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 896452);
