INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63388880', 63388880, 'analyze_legacy', 'Kementerian Kesehatan', 'central', 'SEKRETARIAT DIREKTORAT JENDERAL KESEHATAN LANJUTAN', 'Jasa Konsultasi Penyusunan Pedoman Teknis Pemenuhan Peralatan Kesehatan Layanan Gastrohepatologi', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Selatan (Kota)', 100000000, 'March 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1 Paket', '1. Belanja Jasa Konsultan; Jasa Konsultasi Penyusunan Pedoman Teknis Pemenuhan Peralatan Kesehatan Layanan Gastrohepatologi Uraian pekerjaan meliputi penyusunan Pedoman Teknis Peralatan Kesehatan Layanan Gastrohepatologi sebagai Norma, Standar, Prosedur, dan Kriteria (NSPK). Kegiatan mencakup persiapan, pengumpulan dan pengkajian data, penyusunan draf pedoman, pembahasan dan harmonisasi dengan pemangku kepentingan terkait, finalisasi dokumen, serta diseminasi pedoman. Pedoman disusun sebagai acuan pemenuhan peralatan kesehatan layanan gastrohepatologi sesuai stratifikasi pelayanan rumah sakit jejaring pengampuan.', 'Spesifikasi pekerjaan berupa jasa konsultansi profesional untuk penyusunan Pedoman Teknis Peralatan Kesehatan Layanan Gastrohepatologi. Output pekerjaan berupa satu dokumen NSPK yang memuat standar peralatan kesehatan layanan gastrohepatologi sesuai stratifikasi pelayanan (dasar, madya, utama, dan paripurna). Pelaksanaan pekerjaan mengacu pada ketentuan peraturan perundang-undangan di bidang kesehatan dan rumah sakit, dengan rincian metodologi, tahapan, dan substansi teknis diatur lebih lanjut dalam Kerangka Acuan Kerja (KAK) dan dokumen pemilihan.', 0, 'low', NULL