INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63390032', 63390032, 'analyze_legacy', 'Kementerian Kesehatan', 'central', 'SEKRETARIAT DIREKTORAT JENDERAL KESEHATAN LANJUTAN', 'Persiapan - Belanja Bahan - Bimbingan Teknis Pemenuhan Sarana Prasarana RS UPT Vertikal dan RS Pemerintah', 'Barang', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Selatan (Kota)', 7310000, 'May 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1 Paket', '1. Belanja Bahan; Penyediaan bahan konsumsi rapat rutin berupa makanan dan/atau minuman siap saji untuk mendukung pelaksanaan kegiatan rapat, koordinasi, dan pertemuan kedinasan. Konsumsi disesuaikan dengan jumlah peserta dan waktu pelaksanaan rapat, memenuhi standar kebersihan, keamanan pangan, serta kelayakan konsumsi, dan disediakan sesuai kebutuhan kegiatan.', 'Spesifikasi pekerjaan meliputi penyediaan konsumsi berupa makanan dan snack untuk mendukung pelaksanaan kegiatan. Konsumsi yang disediakan harus dalam kondisi layak, higienis, dan aman dikonsumsi, menggunakan bahan yang baik dan tidak kedaluwarsa, serta disesuaikan dengan jumlah peserta dan waktu pelaksanaan kegiatan. Penyedia bertanggung jawab atas pengadaan, pengemasan, dan penyediaan konsumsi sesuai ketentuan yang berlaku.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 898788);
