INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63344827', 63344827, 'analyze_legacy', 'Kementerian Kesehatan', 'central', 'SEKRETARIAT DIREKTORAT JENDERAL KESEHATAN LANJUTAN', 'Pengadaan Alkes RS dalam rangka Program Peningkatan RS Kelas D menjadi RS Kelas C (PHTC Bidang Kesehatan)', 'Barang', 'E-Purchasing', 'DKI Jakarta, Jakarta Selatan (Kota)', 204948418000, 'March 2026', 'APBN - RUPIAH MURNI (A)', 0, 1, '1 Paket', '1. Belanja Peralatan Dan Mesin Untuk Diserahkan Kepada Masyarakat/Pemda; 2. Belanja Gedung Dan Bangunan Untuk Diserahkan Kepada Masyarakat/Pemda; Pelaksanaan pekerjaan fisik dan penyediaan alkes akan diberikan kepada Pemda melalui mekanisme Banper sesuai ketentuan Peraturan Menteri Kesehatan Nomor 21 Tahun 2022 tentang Perubahan ke Lima Atas Peraturan Menteri Kesehatan Nomor 79 Tahun 2016 Tentang Pedoman Umum Penyaluran Bantuan Pemerintah di Lingkungan Kementerian Kesehatan, Keputusan Direktur Jenderal Pelayanan Kesehatan nomor HK.02.02/D/45967/2024 tentang Petunjuk Teknis Penyaluran Bantuan Pemerintah Dalam Implementasi Program Hasil Terbaik Cepat Berupa Peningkatan Kemampuan Pelayanan Rumah Sakit Dan Penyelenggaraan Pelayanan Rumah Sakit Kapal, dan penetapan Lokus Banper sesuai Surat Keputusan Direktur Jenderal Pelayanan Kesehatan Nomor HK.0202/D/45976/2024 tentang Lokus Bantuan Pemerintah Dalam Implementasi PHTCBerupa Peningkatan Kemampuan Pelayanan Rumah Sakit.', 'Kebutuhan alkes dan mekanisme penyediaan alkes akan dipenuhi melalui pengadaan Pemerintah Pusat dalam hal ini Kementerian Kesehatan dan pada DIPA Direktorat Jenderal Kesehatan Lanjutan TA 2026. Namun sebelum pelaksanaan pemenuhan peralatan kesehatan dan penunjangnya tersebut akan dilakukan desk agar menyesuaikan kebutuhan RSUD lokus banper agar lebih efektif dan efisien terhadap pemenuhannya. Spesifikasi alat kesehatan disusun secara umum untuk mendukung peningkatan kelas rumah sakit dari Kelas D menjadi Kelas C, dengan tujuan memenuhi kebutuhan pelayanan medis sesuai standar rumah sakit rujukan tingkat pertama. Alat kesehatan yang direncanakan meliputi peralatan layanan umum dan penunjang medis yang diperlukan untuk peningkatan kapasitas pelayanan, keselamatan pasien, serta mutu layanan. Alat kesehatan yang diadakan merupakan alat baru, memiliki izin edar dari Kementerian Kesehatan, memenuhi standar mutu dan keselamatan, serta kompatibel dengan sistem dan sarana rumah sakit. Spesifikasi teknis rinci, konfigurasi, dan persyaratan lainnya akan ditetapkan lebih lanjut dalam ketentuan Mini Kompetisi melalui mekanisme e-Purchasing sesuai peraturan perundang-undangan yang berlaku.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 899902);
